1	import React, { useEffect, useRef, useState } from 'react';
2	import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
3	import { defineMessages, useIntl } from 'react-intl';
4	import { ZimmSlideIndicator } from '../zimmSlideIndicator';
5	import { ChevronLeftIcon, ChevronRightIcon, CloseIcon } from '../../../icons';
6	import { CARD_SLOT } from '../../zimmProductCardShared';
7	
8	/**
9	 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
10	 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
11	 * these descendants for hover-reveal styling without reaching into implementation details.
12	 * Do not rename these values without updating that recipe too:
13	 *   - "media"     — the outermost element (this component's root)
14	 *   - "badge"     — the merchandiser badge label, top-left of the image (present only when a
15	 *                   non-empty `badge` is supplied)
16	 *   - "close"     — the remove-CTA button (present only when `onRemove` + a usable label exist)
17	 *   - "carousel"  — the prev/next arrows wrapper (present only when paging is enabled)
18	 *   - "indicator" — the touch slide-indicator wrapper (present only when there is >1 image)
19	 */
20	
21	const messages = defineMessages({
22	  previousImage: { id: 'product_card_media.pagination.previous', defaultMessage: 'Previous image' },
23	  nextImage: { id: 'product_card_media.pagination.next', defaultMessage: 'Next image' },
24	  /**
25	   * Accessible name for the always-available keyboard-operable scroll container (WCAG 2.1.1) —
26	   * distinct from the hover-capable-only `carousel` arrows and the touch-only
27	   * `indicatorWrapper`, this is the underlying paging affordance that exists regardless of
28	   * pointer capability. See `canNavigateByKeyboard` below.
29	   */
30	  galleryLabel: { id: 'product_card_media.gallery.label', defaultMessage: 'Product images' },
31	});
32	
33	const ZIMM_PRODUCT_CARD_MEDIA_RECIPE = 'ZimmProductCardMedia';
34	
35	/** One image the card can show — always a real, non-empty product-photo description. */
36	export type ZimmProductCardMediaImage = {
37	  src: string;
38	  alt: string;
39	};
40	
41	export type ZimmProductCardMediaProps = {
42	  /** The image shown when nothing else applies — always required, even when `images` is supplied. */
43	  primaryImage: ZimmProductCardMediaImage;
44	  /**
45	   * The second image revealed on hover (desktop/hover-capable pointers only), crossfading with
46	   * `primaryImage`. Ignored while a multi-image `images` gallery is active (>1 entries) — the
47	   * arrows/indicator paging affordances already give a shopper a way to browse every image, so
48	   * a hover-swap of just the first two would be a second, inconsistent way to see the same
49	   * content. Has no effect unless `swapOnHover` is also true.
50	   */
51	  hoverImage?: ZimmProductCardMediaImage;
52	  /**
53	   * The full orderable gallery for this card. Only takes over from `primaryImage` when it has
54	   * more than one entry — 0 or 1 entries behaves exactly like an absent `images` (see
55	   * `hoverImage`'s note above for why the two features don't combine).
56	   */
57	  images?: ZimmProductCardMediaImage[];
58	  /** Enables the primary/hover crossfade described on `hoverImage`. Has no effect without it. */
59	  swapOnHover: boolean;
60	  /**
61	   * Enables the desktop prev/next arrows. The touch slide-indicator is independent of this flag
62	   * (per the Figma "Image Group" spec, the touch variant has no separate "controls off" state)
63	   * — it renders whenever there is more than one image to page through, regardless of this prop.
64	   */
65	  showControls: boolean;
66	  /**
67	   * Merchandiser-configured badge label (e.g. "Runway", "Exclusive") — SFCC-236's Figma "Tag"
68	   * overlay, top-left of the image. Renders only when non-empty; a blank/whitespace-only value
69	   * behaves identically to omitting the prop, same guard shape as `removeLabel` below. Which
70	   * variations actually show a badge (PLP/Wishlist yes, Home no) is the organism's job via its
71	   * `VARIATION_CONFIG` — this component only renders what it's given.
72	   */
73	  badge?: string;
74	  /** Wishlist-only remove action. Rendered only when paired with a usable `removeLabel`. */
75	  onRemove?: () => void;
76	  /**
77	   * Accessible name for the remove button — required in practice whenever `onRemove` is passed
78	   * (typically the product name, e.g. "Remove {productName} from wishlist"). Modelled as two
79	   * independent optional props rather than a discriminated union because this is a simple
80	   * co-requirement, not a real variant split: if `onRemove` is supplied without a usable
81	   * (non-empty, non-whitespace) `removeLabel`, the remove button silently does not render at
82	   * all rather than shipping an unlabelled, inaccessible button — see the component body.
83	   */
84	  removeLabel?: string;
85	  /**
86	   * LCP escape hatch for the primary image slot. Defaults to lazy-loading — this component has
87	   * no way to know whether it sits above the fold, so the safer default is lazy; a caller that
88	   * knows it renders above the fold (AGENTS.md's "LCP ≤2s p75 mobile" priority) should pass
89	   * `priority`. Has no effect on any non-primary image, which is always lazy regardless.
90	   */
91	  priority?: boolean;
92	  /**
93	   * Optional click handler on this component's own root — forwarded as-is, with no navigation
94	   * logic of its own (Media stays navigation-agnostic; the composing organism decides what a
95	   * click means and which of Media's own buttons to exclude from it). Added for SFCC-236 Fix I —
96	   * see the composing `ZimmProductCard` organism's own docblock for the full narrative.
97	   */
98	  onClick?: React.MouseEventHandler<HTMLDivElement>;
99	};
100	
101	/**
102	 * Molecule — the product-card media block: a single image, a hover-swap pair, or a full
103	 * scroll-snap gallery with desktop arrows / touch slide-indicator, plus the wishlist-remove
104	 * overlay slot. Figma "Image Group" component set, node 40002742:46323.
105	 *
106	 * Touch paging is native CSS scroll-snap at every breakpoint; arrows are a progressive
107	 * enhancement over the same scroll container, never a second, independent mechanism. Arrows and
108	 * the slide indicator are mutually exclusive by pointer capability
109	 * (`(hover: hover) and (pointer: fine)`) and never both interactively visible at once. Both
110	 * exist in the DOM at all times, gated via CSS rather than a JS `window.matchMedia` check —
111	 * matching the "keep in DOM, hide via CSS" precedent `ZimmColourSwatchGroup` already uses for its
112	 * off-page swatches — so server and client render identically (no hydration mismatch) and
113	 * neither affordance depends on `matchMedia`, which jsdom (this component's own Vitest
114	 * environment) does not implement. The two affordances differ in *where* that CSS lives, though:
115	 * the indicator is fully gated by this recipe's own media query. The arrows are not — this
116	 * recipe only ever sets them to `display: none`; the actual reveal (`display: flex`, on
117	 * `&:hover`/`&:has(:focus-visible)`) lives in the composing `ZimmProductCard` organism's own recipe,
118	 * since the AC and Figma both specify arrows appear on an actual hover/focus interaction with the
119	 * whole card, not merely "device supports hover" — the same interaction-gated pattern already
120	 * used there for price/size-chips/notify-me. A story rendering this component standalone (see
121	 * this file's own `index.stories.tsx`) therefore never shows the arrows, by design.
122	 *
123	 * A third, always-available operability layer sits underneath both visual affordances: the
124	 * scroll container itself is keyboard-focusable and handles ArrowLeft/ArrowRight directly
125	 * whenever there is more than one slide, regardless of pointer capability or `showControls` —
126	 * a hover-incapable pointer previously had no way to page the gallery via keyboard at all
127	 * (WCAG 2.1.1), since the arrows are `display:none` there and the indicator has no focusable
128	 * content. See `canNavigateByKeyboard` / `handleScrollContainerKeyDown` below.
129	 */
130	export const ZimmProductCardMedia = ({
131	  primaryImage,
132	  hoverImage,
133	  images,
134	  swapOnHover,
135	  showControls,
136	  badge,
137	  onRemove,
138	  removeLabel,
139	  priority,
140	  onClick,
141	}: ZimmProductCardMediaProps) => {
142	  const intl = useIntl();
143	  const styles = useMultiStyleConfig(ZIMM_PRODUCT_CARD_MEDIA_RECIPE, {});
144	
145	  // >1 entries takes over as the full slide list; 0 or 1 behaves like no gallery at all (see
146	  // the `images` prop's own JSDoc for why hover-swap and the gallery don't combine).
147	  const gallery = images && images.length > 1 ? images : undefined;
148	  const slideImages = gallery ?? [primaryImage];
149	  const totalSlides = slideImages.length;
150	  const showHoverSwap = swapOnHover && Boolean(hoverImage) && !gallery;
151	  const canPage = totalSlides > 1 && showControls;
152	  // Keyboard operability is independent of `showControls` — deliberately not folded into
153	  // `canPage` above (WCAG 2.1.1): a hover-incapable pointer (a touchscreen with a physical
154	  // keyboard attached, switch access, or a desktop browser reporting `hover:none`) has the
155	  // arrows hidden by the recipe's own media query and the indicator has no focusable content,
156	  // so this is the only paging affordance such a user has, regardless of `showControls`.
157	  const canNavigateByKeyboard = totalSlides > 1;
158	
159	  // Single piece of state, per this codebase's extract-to-hook threshold
160	  // (.claude/rules/components.md). Kept inline — including the scroll-tracking and
161	  // index-clamping effects below — rather than pulled into a useProductCardMediaScroll hook,
162	  // because this build step's file manifest is limited to this component's own 4 files; a hook
163	  // would be a 5th file outside that scope.
164	  const [currentIndex, setCurrentIndex] = useState(0);
165	  const scrollContainerRef = useRef<HTMLDivElement>(null);
166	
167	  const scrollToIndex = (index: number) => {
168	    const container = scrollContainerRef.current;
169	    if (!container || typeof container.scrollTo !== 'function') return;
170	    // clientWidth is 0 under jsdom (no real layout) — the call still fires with a plausible
171	    // {left, behavior} shape, which is what this component's own Vitest suite asserts; a real
172	    // browser reports a real width so the requested slide scrolls fully into view.
173	    container.scrollTo({ left: index * container.clientWidth, behavior: 'smooth' });
174	  };
175	
176	  const goToRelativeSlide = (delta: 1 | -1) => {
177	    if (totalSlides <= 1) return;
178	    const next = (currentIndex + delta + totalSlides) % totalSlides;
179	    setCurrentIndex(next);
180	    scrollToIndex(next);
181	  };
182	
183	  // Re-clamps currentIndex whenever the slide count shrinks while this instance stays mounted
184	  // (e.g. a colour-variant swap that reduces the gallery from 3 images to 2) — same "clamp to
185	  // the highest valid index" precedent as ZimmColourSwatchGroup's own page-clamp effect
186	  // (../zimmColourSwatchGroup/index.tsx:75-84). Without this, currentIndex stays at the stale,
187	  // out-of-range value: ZimmSlideIndicator's own display-side clamp masks it visually right
188	  // after the shrink, but goToRelativeSlide's modulo arithmetic above still computes from the
189	  // stale, unclamped state, so the very next Next/Previous click is a silent no-op.
190	  useEffect(() => {
191	    setCurrentIndex((index) => Math.min(index, totalSlides - 1));
192	  }, [totalSlides]);
193	
194	  // Arrow-key paging on the scroll container itself, reachable regardless of pointer
195	  // capability — additive to, and independent of, the hover-capable-only arrows and the
196	  // touch-only indicator above (see canNavigateByKeyboard's own comment for why). Same
197	  // "check the key, then preventDefault" idiom as ZimmColourSwatchGroup's own
198	  // handleSwatchesKeyDown (../zimmColourSwatchGroup/index.tsx:109-111).
199	  const handleScrollContainerKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
200	    if (!['ArrowLeft', 'ArrowRight'].includes(event.key)) return;
201	    event.preventDefault();
202	    goToRelativeSlide(event.key === 'ArrowRight' ? 1 : -1);
203	  };
204	
205	  // Keeps the touch slide-indicator's active dot following native swipe paging, which never
206	  // calls goToRelativeSlide at all. `scrollend` (Baseline 2024 — Chrome 114+, Firefox 109+,
207	  // Safari 18+) fires once the snap gesture settles. No `scroll`-event fallback for older
208	  // Safari: CSS scroll-snap paging itself is unaffected either way — the indicator dot simply
209	  // lags on an unsupported browser, a minor, graceful degradation rather than a broken
210	  // interaction.
211	  useEffect(() => {
212	    const container = scrollContainerRef.current;
213	    if (!container || totalSlides <= 1) return undefined;
214	
215	    const handleScrollEnd = () => {
216	      const slideWidth = container.clientWidth || 1;
217	      const nearest = Math.round(container.scrollLeft / slideWidth);
218	      setCurrentIndex(Math.min(Math.max(nearest, 0), totalSlides - 1));
219	    };
220	
221	    container.addEventListener('scrollend', handleScrollEnd);
222	    return () => container.removeEventListener('scrollend', handleScrollEnd);
223	  }, [totalSlides]);
224	
225	  // Non-primary images are always lazy; only the first slide's own base image can opt into
226	  // eager loading via `priority`. See that prop's own JSDoc for the default-to-lazy reasoning.
227	  const imageLoadingProps = (isPrimaryPosition: boolean): { loading?: 'lazy'; decoding: 'async' } =>
228	    isPrimaryPosition && priority ? { decoding: 'async' } : { loading: 'lazy', decoding: 'async' };
229	
230	  const hasUsableRemoveLabel = typeof removeLabel === 'string' && removeLabel.trim().length > 0;
231	  const showRemove = Boolean(onRemove) && hasUsableRemoveLabel;
232	  const hasBadge = typeof badge === 'string' && badge.trim().length > 0;
233	
234	  return (
235	    <chakra.div __css={styles.root} data-card-slot={CARD_SLOT.media} onClick={onClick}>
236	      <chakra.div
237	        ref={scrollContainerRef}
238	        __css={styles.scrollContainer}
239	        data-testid="card-media-scroll"
240	        role={canNavigateByKeyboard ? 'group' : undefined}
241	        aria-label={canNavigateByKeyboard ? intl.formatMessage(messages.galleryLabel) : undefined}
242	        tabIndex={canNavigateByKeyboard ? 0 : undefined}
243	        onKeyDown={canNavigateByKeyboard ? handleScrollContainerKeyDown : undefined}
244	      >
245	        {slideImages.map((image, index) => {
246	          const isPrimaryPosition = index === 0;
247	
248	          if (isPrimaryPosition && showHoverSwap && hoverImage) {
249	            return (
250	              <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
251	                <chakra.img
252	                  src={image.src}
253	                  alt={image.alt}
254	                  data-role="hover-base"
255	                  __css={styles.hoverSwapBase}
256	                  {...imageLoadingProps(true)}
257	                />
258	                <chakra.img
259	                  src={hoverImage.src}
260	                  alt={hoverImage.alt}
261	                  data-role="hover-overlay"
262	                  __css={styles.hoverSwapOverlay}
263	                  {...imageLoadingProps(false)}
264	                />
265	              </chakra.div>
266	            );
267	          }
268	
269	          return (
270	            <chakra.div key={`${image.src}-${index}`} __css={styles.slide}>
271	              <chakra.img
272	                src={image.src}
273	                alt={image.alt}
274	                __css={styles.image}
275	                {...imageLoadingProps(isPrimaryPosition)}
276	              />
277	            </chakra.div>
278	          );
279	        })}
280	      </chakra.div>
281	
282	      {hasBadge && (
283	        <chakra.div __css={styles.badge} data-card-slot={CARD_SLOT.badge}>
284	          <chakra.span __css={styles.badgeLabel}>{badge}</chakra.span>
285	        </chakra.div>
286	      )}
287	
288	      {showRemove && (
289	        <chakra.button
290	          type="button"
291	          __css={styles.close}
292	          data-card-slot={CARD_SLOT.close}
293	          aria-label={removeLabel}
294	          onClick={onRemove}
295	        >
296	          <CloseIcon aria-hidden boxSize="var(--zimm-icon-size-md)" />
297	        </chakra.button>
298	      )}
299	
300	      {canPage && (
301	        <chakra.div __css={styles.carousel} data-card-slot={CARD_SLOT.carousel}>
302	          <chakra.button
303	            type="button"
304	            __css={styles.arrowButton}
305	            aria-label={intl.formatMessage(messages.previousImage)}
306	            onClick={() => goToRelativeSlide(-1)}
307	          >
308	            <ChevronLeftIcon aria-hidden />
309	          </chakra.button>
310	          <chakra.button
311	            type="button"
312	            __css={styles.arrowButton}
313	            aria-label={intl.formatMessage(messages.nextImage)}
314	            onClick={() => goToRelativeSlide(1)}
315	          >
316	            <ChevronRightIcon aria-hidden />
317	          </chakra.button>
318	        </chakra.div>
319	      )}
320	
321	      {totalSlides > 1 && (
322	        <chakra.div __css={styles.indicatorWrapper} data-card-slot={CARD_SLOT.indicator}>
323	          <ZimmSlideIndicator count={totalSlides} activeIndex={currentIndex} />
324	        </chakra.div>
325	      )}
326	    </chakra.div>
327	  );
328	};
329	
330	export default ZimmProductCardMedia;
331

