313	    // Hover-capable pointers: indicatorWrapper still hides itself via its own
314	    // `[HOVER_CAPABLE_QUERY]` key (unchanged by this fix) — but `carousel` no longer has a
315	    // `[HOVER_CAPABLE_QUERY]` key AT ALL. Regression guard: if that key ever reappears here with
316	    // an unconditional `display: 'flex'`, the permanent-visibility bug is back.
317	    const carousel = style.carousel as Record<string, unknown>;
318	    const indicatorWrapper = style.indicatorWrapper as Record<string, unknown>;
319	    expect(carousel[HOVER_CAPABLE_QUERY]).toBeUndefined();
320	    const indicatorHoverBlock = indicatorWrapper[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
