352	  test('navigating to the last of 3 images then shrinking to 2 wraps correctly on the very next click', async () => {
353	    const user = userEvent.setup();
354	    const utils = wrap(
355	      <ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />,
356	    );
357	
358	    const next = screen.getByRole('button', { name: 'Next image' });
