365	    const SHRUNK_GALLERY = GALLERY.slice(0, 2);
366	    utils.rerender(
367	      <IntlProvider locale="en" defaultLocale="en">
368	        <ZimmProductCardMedia primaryImage={PRIMARY} images={SHRUNK_GALLERY} swapOnHover={false} showControls />
369	      </IntlProvider>,
370	    );
371	
372	    // ZimmSlideIndicator's own display-side clamp masks the stale state right here too — it also
373	    // reads "2 of 2", which is exactly what makes the underlying bug invisible without also
374	    // exercising the very next click below.
375	    expect(screen.getByRole('group', { name: 'Image 2 of 2' })).toBeInTheDocument();
376	
377	    const nextAfterShrink = screen.getByRole('button', { name: 'Next image' });
378	    await user.click(nextAfterShrink); // must wrap 2nd -> 1st on THIS click, not require a second one
379	
380	    expect(screen.getByRole('group', { name: 'Image 1 of 2' })).toBeInTheDocument();
