384	describe('ZimmProductCardMedia — scrollend listener drives the touch indicator (Fix 4 regression)', () => {
385	  test('a real scrollend event with a simulated scroll position updates the indicator', () => {
386	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
387	    const container = screen.getByTestId('card-media-scroll');
