390	    // but they ARE plain definable properties, so a real geometry can be simulated directly.
391	    // Slide width 300 x 3 slides, scrolled to slide index 1 (the 2nd of 3) => scrollLeft 300.
392	    const SIMULATED_SLIDE_WIDTH = 300;
393	    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
394	    Object.defineProperty(container, 'scrollWidth', {
395	      value: SIMULATED_SLIDE_WIDTH * GALLERY.length,
396	      configurable: true,
397	    });
398	    Object.defineProperty(container, 'scrollLeft', { value: SIMULATED_SLIDE_WIDTH * 1, configurable: true });
