import React from 'react';
import { describe, test, expect, vi, afterEach } from 'vitest';
import { render, screen, fireEvent, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { ChakraProvider } from '@chakra-ui/react';
import theme from 'app/theme';
import { ListMenuPopover } from './list-menu-popover';
import type { MegaMenuMotionPhase } from 'app/hooks/useMegaMenuMotion';
import type { HeaderNavItemEntry } from 'app/types/contentful';

afterEach(() => vi.clearAllMocks());

// list-menu-popover.tsx statically imports base SFCC's list-menu-content.jsx as its default
// contentComponent fallback — that import happens unconditionally at module-evaluation time
// regardless of the contentComponent prop actually passed at render time, and transitively
// pulls in links-list -> link -> use-multi-site -> the base contexts barrel, a `.js` file with
// raw JSX Vite's import-analysis can't parse under Vitest. Mocking it at this exact boundary
// (not the whole shared/ui barrel) is the smallest surface that stops the chain — same
// reasoning as list-menu.test.tsx's own vi.mock('./list-menu-popover').
vi.mock('@salesforce/retail-react-app/app/components/list-menu/list-menu-content', () => ({
  ListMenuContent: () => null,
}));

// list-menu-trigger.tsx renders ChevronDownIcon from the overrides icons barrel (fixed in this
// same change — it previously imported the base template's filled chevron directly, per
// icons/index.tsx's own comment that Zimmermann's stroked chevrons are deliberately not
// re-exported from base). That barrel also re-exports many other base icons in the same file,
// and evaluating it at all pulls in the base icons module's top-level side effect
// (`AmexSymbol.viewBox = ...`), which throws under Vitest — the same documented
// "ZimmIcon throws under Vitest" gap in .claude/rules/testing.md, surfacing here through the
// barrel itself rather than the ZimmIcon wrapper, since this is the first suite to render
// list-menu-trigger.tsx for real.
vi.mock('app/components/icons', () => ({ ChevronDownIcon: () => null }));

// A trivial stub, not the real MegaMenuContent/base ListMenuContent — this suite's job is
// ListMenuPopover's own contract (does it wire the controlled isOpen/onOpen/onClose props to
// the right places, does it forward item/itemsKey/maxColumns to whatever contentComponent it's
// given), not any particular content component's rendering. Passing a stub explicitly also
// sidesteps ListMenuPopover's *default* contentComponent fallback (base SFCC's
// list-menu-content.jsx, a `.js` file with raw JSX Vite's import-analysis can't parse under
// Vitest — see list-menu.test.tsx's own comment on this) by never triggering it.
const StubContent = ({
  item,
  itemsKey,
  maxColumns,
  onClose,
  isOpen,
  isFullyOpen,
  initialFocusRef,
}: {
  item?: HeaderNavItemEntry;
  itemsKey?: string;
  maxColumns?: number;
  onClose?: () => void;
  isOpen?: boolean;
  isFullyOpen?: boolean;
  initialFocusRef?: React.RefObject<HTMLElement>;
}) => (
  <div
    data-testid="stub-content"
    data-items-key={itemsKey}
    data-max-columns={maxColumns}
    data-is-open={isOpen}
    data-is-fully-open={isFullyOpen}
    ref={initialFocusRef as React.RefObject<HTMLDivElement>}
  >
    {item?.fields.label}
    <a href="#panel-link" data-testid="panel-link">
      panel-link
    </a>
    <button onClick={onClose}>close-content</button>
  </div>
);

const megaMenuItem = (id: string, label: string): HeaderNavItemEntry => ({
  sys: { id, contentType: { sys: { id: 'headerNavItem' } } },
  fields: { label, columns: [] },
});

const renderPopover = (props: Partial<React.ComponentProps<typeof ListMenuPopover>> = {}) => {
  const onOpen = vi.fn();
  const onClose = vi.fn();
  const utils = render(
    <ChakraProvider theme={theme}>
      <ListMenuPopover
        item={megaMenuItem('clothing', 'Clothing')}
        name="Clothing"
        itemsKey="columns"
        maxColumns={5}
        contentComponent={StubContent}
        isOpen={false}
        onOpen={onOpen}
        onClose={onClose}
        {...props}
      />
    </ChakraProvider>,
  );
  return { ...utils, onOpen, onClose };
};

describe('ListMenuPopover', () => {
  test('forwards item, itemsKey, and maxColumns to the given contentComponent', () => {
    renderPopover();

    const content = screen.getByTestId('stub-content');
    expect(content).toHaveTextContent('Clothing');
    expect(content).toHaveAttribute('data-items-key', 'columns');
    expect(content).toHaveAttribute('data-max-columns', '5');
  });

  test("gives the popover dialog an accessible name — regression guard: axe flagged this as a real violation once a real interaction actually opened the popover (aria-dialog-name), a pre-existing gap in both this override and base SFCC's own list-menu-popover.jsx", () => {
    renderPopover();

    expect(screen.getByTestId('popover-menu')).toHaveAttribute('aria-label', 'Clothing menu');
  });

  test('is a controlled component — isOpen is driven entirely by the prop, not internal state', () => {
    const { rerender } = renderPopover({ isOpen: false });
    expect(screen.getByTestId('stub-content')).toHaveAttribute('data-is-open', 'false');

    rerender(
      <ChakraProvider theme={theme}>
        <ListMenuPopover
          item={megaMenuItem('clothing', 'Clothing')}
          name="Clothing"
          itemsKey="columns"
          maxColumns={5}
          contentComponent={StubContent}
          isOpen={true}
          onOpen={vi.fn()}
          onClose={vi.fn()}
        />
      </ChakraProvider>,
    );

    expect(screen.getByTestId('stub-content')).toHaveAttribute('data-is-open', 'true');
  });

  test('hovering the trigger label calls the given onOpen, not an internally-owned disclosure', async () => {
    const { onOpen } = renderPopover();

    await userEvent.hover(screen.getByRole('button', { name: 'Clothing' }));

    expect(onOpen).toHaveBeenCalledTimes(1);
  });

  test('content calling its own onClose calls the given onClose, not an internally-owned disclosure', async () => {
    const { onClose } = renderPopover({ isOpen: true });

    await userEvent.click(screen.getByRole('button', { name: 'close-content' }));

    expect(onClose).toHaveBeenCalledTimes(1);
  });

  // Regression guard (CodeRabbit, PR #65): a pending (isOpen=true, isActiveItem=false) instance's
  // `phase` is permanently 'closed' (see the `phase` derivation in list-menu-popover.tsx), so a
  // Down Arrow pressed while merely pending arms pendingEnterPanelRef with no `phase` transition
  // to ever clear it again — an isOpen-less effect dependency array can't see the later isOpen
  // flip to false either. Without isOpen in the effect's dependencies, that stale request would
  // fire the next time this item opens for real via a plain pointer hover, moving focus with no
  // new keyboard input.
  test('a stale Down-Arrow request from when an item was only pending (not yet active) does not move focus once it later opens for real via a plain hover', async () => {
    const { rerender } = renderPopover({ isOpen: true, isActiveItem: false, motionPhase: 'contentOut' });

    fireEvent.keyDown(screen.getByRole('button', { name: 'Clothing' }), { key: 'ArrowDown' });

    // The pending item closes again (e.g. the user hovered elsewhere) without ever becoming
    // active/open — its own `phase` never leaves 'closed', only `isOpen` changes.
    rerender(
      <ChakraProvider theme={theme}>
        <ListMenuPopover
          item={megaMenuItem('clothing', 'Clothing')}
          name="Clothing"
          itemsKey="columns"
          maxColumns={5}
          contentComponent={StubContent}
          isOpen={false}
          isActiveItem={false}
          motionPhase="closed"
          onOpen={vi.fn()}
          onClose={vi.fn()}
        />
      </ChakraProvider>,
    );

    // It later opens for real via a plain pointer hover and reaches the fully-open phase.
    rerender(
      <ChakraProvider theme={theme}>
        <ListMenuPopover
          item={megaMenuItem('clothing', 'Clothing')}
          name="Clothing"
          itemsKey="columns"
          maxColumns={5}
          contentComponent={StubContent}
          isOpen={true}
          isActiveItem={true}
          motionPhase="open"
          onOpen={vi.fn()}
          onClose={vi.fn()}
        />
      </ChakraProvider>,
    );

    await waitFor(() => expect(screen.getByTestId('stub-content')).toHaveAttribute('data-is-fully-open', 'true'));
    expect(screen.getByTestId('panel-link')).not.toHaveFocus();
  });

  // Motion (SFCC-52, 2026-08-29) — the reducer's own phase sequencing has its coverage in
  // useMegaMenuMotion.test.ts; this suite covers the *mapping* from a given phase to the actual
  // CSS this component renders, and the onTransitionEnd -> completion-callback wiring, per
  // list-menu-popover.tsx's own isPanelExpanded/isPanelHeightAnimating/isContentVisible helpers.
  describe('motion phase -> CSS mapping', () => {
    // heightAnimates (isPanelHeightAnimating) is exercised by the onTransitionEnd tests below,
    // not asserted here directly: jsdom can't resolve a `sx`-prop transition value that
    // interpolates a CSS custom property back through getComputedStyle/toHaveStyle (confirmed
    // via a standalone repro — it always reads back 'none' regardless of the real value, the
    // same class of jsdom/emotion stylesheet-parsing gap this suite's "Could not parse CSS
    // stylesheet" warnings already reflect) — gridTemplateRows/opacity, by contrast, read back
    // correctly, so those are what this table asserts.
    const casesByPhase: Array<{ phase: MegaMenuMotionPhase; gridTemplateRows: string; opacity: string }> = [
      { phase: 'expanding', gridTemplateRows: '1fr', opacity: '0' },
      { phase: 'contentIn', gridTemplateRows: '1fr', opacity: '1' },
      { phase: 'open', gridTemplateRows: '1fr', opacity: '1' },
      { phase: 'contentOut', gridTemplateRows: '1fr', opacity: '0' },
      { phase: 'collapsing', gridTemplateRows: '0fr', opacity: '0' },
      { phase: 'closed', gridTemplateRows: '0fr', opacity: '0' },
    ];

    test.each(casesByPhase)(
      'phase "$phase": gridTemplateRows $gridTemplateRows, opacity $opacity',
      async ({ phase, gridTemplateRows, opacity }) => {
        renderPopover({ isOpen: true, isActiveItem: true, motionPhase: phase });

        // gridTemplateRows specifically may apply after a real (double-rAF-deferred) delay for
        // 'expanding' — see list-menu-popover.tsx's useTransitionSafeValue for why: enabling the
        // CSS transition and changing the target value in the same commit doesn't animate, so the
        // fix defers the value change by two frames whenever it should animate. Every other phase
        // in this table either targets the same value it started at or doesn't animate at all, so
        // waitFor resolves immediately for those — this only meaningfully waits for 'expanding'.
        await waitFor(() => expect(screen.getByTestId('panel-reveal')).toHaveStyle({ gridTemplateRows }));
        expect(screen.getByTestId('panel-content-fade')).toHaveStyle({ opacity });
      },
    );

    // isFullyOpen (forwarded to the content component so it can pull leaf links out of Tab
    // order — see megaMenuContent/index.tsx's own doc comment) is true for 'open' only, not
    // 'contentIn' — content is still fading in during 'contentIn', not yet genuinely visible.
    test.each(casesByPhase.map(({ phase }) => ({ phase, isFullyOpen: phase === 'open' })))(
      'phase "$phase": isFullyOpen is $isFullyOpen',
      ({ phase, isFullyOpen }) => {
        renderPopover({ isOpen: true, isActiveItem: true, motionPhase: phase });

        expect(screen.getByTestId('stub-content')).toHaveAttribute('data-is-fully-open', String(isFullyOpen));
      },
    );

    // Regression guard for the real bug this fixed: enabling a CSS transition and changing its
    // target value in the same React commit gives the browser no prior painted frame to
    // interpolate from, so it silently snaps to the target instantly with no `transitionend`
    // ever firing — which permanently stalled useMegaMenuMotion's phase machine (confirmed live
    // against a real browser build, 2026-08-29: grid-template-rows reached its final pixel
    // value within 50ms of the very first render, zero interpolation). This test only proves
    // the deferral itself happens — it doesn't and can't prove *why* it's needed (jsdom doesn't
    // run real CSS transitions), so it stays paired with the live-browser finding above.
    test("'expanding' starts at 0fr and only reaches 1fr after the value is deferred a frame — not synchronously on first render", async () => {
      renderPopover({ isOpen: true, isActiveItem: true, motionPhase: 'expanding' });

      expect(screen.getByTestId('panel-reveal')).toHaveStyle({ gridTemplateRows: '0fr' });
      await waitFor(() => expect(screen.getByTestId('panel-reveal')).toHaveStyle({ gridTemplateRows: '1fr' }));
    });

    test('an inactive instance (isOpen=false) always renders the closed resting state, regardless of the shared motionPhase prop', () => {
      renderPopover({ isOpen: false, isActiveItem: false, motionPhase: 'open' });

      expect(screen.getByTestId('panel-reveal')).toHaveStyle({ gridTemplateRows: '0fr' });
      expect(screen.getByTestId('panel-content-fade')).toHaveStyle({ opacity: '0' });
    });

    test('a pending item (isOpen=true, isActiveItem=false) — the incoming item during a switch — stays at the closed CSS resting state even though its Popover is already open', () => {
      // The whole point of the isOpen/isActiveItem split: the incoming item's Popover mounts
      // and positions early (isOpen=true) so there's no floating-ui positioning left to do at
      // the moment it actually takes over, but it must not be visually revealed before then.
      renderPopover({ isOpen: true, isActiveItem: false, motionPhase: 'contentOut' });

      expect(screen.getByTestId('panel-reveal')).toHaveStyle({ gridTemplateRows: '0fr' });
      expect(screen.getByTestId('panel-content-fade')).toHaveStyle({ opacity: '0' });
    });

    test('the height reveal completing calls onExpandComplete only during the expanding phase', () => {
      const onExpandComplete = vi.fn();
      const onCollapseComplete = vi.fn();
      renderPopover({
        isOpen: true,
        isActiveItem: true,
        motionPhase: 'expanding',
        onExpandComplete,
        onCollapseComplete,
      });

      fireEvent.transitionEnd(screen.getByTestId('panel-reveal'));

      expect(onExpandComplete).toHaveBeenCalledTimes(1);
      expect(onCollapseComplete).not.toHaveBeenCalled();
    });

    test('the height collapse completing calls onCollapseComplete only during the collapsing phase', () => {
      const onExpandComplete = vi.fn();
      const onCollapseComplete = vi.fn();
      renderPopover({
        isOpen: true,
        isActiveItem: true,
        motionPhase: 'collapsing',
        onExpandComplete,
        onCollapseComplete,
      });

      fireEvent.transitionEnd(screen.getByTestId('panel-reveal'));

      expect(onCollapseComplete).toHaveBeenCalledTimes(1);
      expect(onExpandComplete).not.toHaveBeenCalled();
    });

    test('a transitionend on the reveal wrapper during a steady phase (open) calls neither height callback', () => {
      const onExpandComplete = vi.fn();
      const onCollapseComplete = vi.fn();
      renderPopover({ isOpen: true, isActiveItem: true, motionPhase: 'open', onExpandComplete, onCollapseComplete });

      fireEvent.transitionEnd(screen.getByTestId('panel-reveal'));

      expect(onExpandComplete).not.toHaveBeenCalled();
      expect(onCollapseComplete).not.toHaveBeenCalled();
    });

    test('the content fade-in completing calls onContentInComplete only during the contentIn phase', () => {
      const onContentInComplete = vi.fn();
      const onContentOutComplete = vi.fn();
      renderPopover({
        isOpen: true,
        isActiveItem: true,
        motionPhase: 'contentIn',
        onContentInComplete,
        onContentOutComplete,
      });

      fireEvent.transitionEnd(screen.getByTestId('panel-content-fade'));

      expect(onContentInComplete).toHaveBeenCalledTimes(1);
      expect(onContentOutComplete).not.toHaveBeenCalled();
    });

    test('the content fade-out completing calls onContentOutComplete only during the contentOut phase', () => {
      const onContentInComplete = vi.fn();
      const onContentOutComplete = vi.fn();
      renderPopover({
        isOpen: true,
        isActiveItem: true,
        motionPhase: 'contentOut',
        onContentInComplete,
        onContentOutComplete,
      });

      fireEvent.transitionEnd(screen.getByTestId('panel-content-fade'));

      expect(onContentOutComplete).toHaveBeenCalledTimes(1);
      expect(onContentInComplete).not.toHaveBeenCalled();
    });
  });
});

