 * fires once the gesture settles) — confirmed live once a related fix made the swipe gesture
 * itself reachable for the first time. These tests cover the `scroll`-driven live-tracking path
 * added alongside it: see index.tsx's own updated comment above the effect for the full
 * reasoning. jsdom (this suite's Vitest environment) implements a real, timer-backed
 * `requestAnimationFrame`, so the throttled update is genuinely asynchronous here, not merely
 * simulated — the same real-rAF-plus-`waitFor` precedent already used by
 * list-menu-popover.test.tsx's own double-rAF-deferred assertions.
 */
describe('ZimmProductCardMedia — scroll listener drives the touch indicator live during an active drag', () => {
  const SIMULATED_SLIDE_WIDTH = 300;

  /** Same "jsdom performs no real layout, but these are plain definable properties" approach as
   *  the `scrollend` test above — sets a plausible clientWidth/scrollWidth/scrollLeft for a
   *  given slide index directly. */
  const simulateScrollPosition = (container: HTMLElement, slideIndex: number) => {
    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
    Object.defineProperty(container, 'scrollWidth', {
      value: SIMULATED_SLIDE_WIDTH * GALLERY.length,
      configurable: true,
    });
    Object.defineProperty(container, 'scrollLeft', { value: SIMULATED_SLIDE_WIDTH * slideIndex, configurable: true });
  };

  test('a real scroll event with a simulated scroll position updates the indicator once the throttled animation frame runs', async () => {
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
    const container = screen.getByTestId('card-media-scroll');
    simulateScrollPosition(container, 1); // 2nd of 3 slides

    // fireEvent (not a raw dispatchEvent) routes through RTL's act()-wrapping config, same
    // reasoning as the scrollend test above — necessary here too even though the resulting
    // setCurrentIndex call is additionally deferred behind a real requestAnimationFrame.
    fireEvent(container, new Event('scroll'));

    // Unlike the scrollend path, this update is intentionally NOT synchronous — it is coalesced
    // behind a real requestAnimationFrame callback, so the assertion has to wait it out rather
    // than read the DOM immediately.
    await waitFor(() => expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument());
  });

  test('several scroll events fired before the pending animation frame runs are coalesced into a single requestAnimationFrame call, not one per event', async () => {
    // spyOn (no mockImplementation) still calls through to jsdom's real rAF — this only adds a
    // call-count tripwire on top of the real, unthrottled behavior it would otherwise have.
    const rafSpy = vi.spyOn(window, 'requestAnimationFrame');
    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
    const container = screen.getByTestId('card-media-scroll');
    simulateScrollPosition(container, 1);

    // Simulates the many `scroll` events a real touch-driven drag fires per second, all
    // dispatched before the browser has had any chance to run the first queued animation frame.
    fireEvent(container, new Event('scroll'));
    fireEvent(container, new Event('scroll'));
    fireEvent(container, new Event('scroll'));

    // The `rafId !== null` guard means only the FIRST of the three calls above actually schedules
    // a frame — this is the throttling behavior itself, not merely "it eventually updates".
    expect(rafSpy).toHaveBeenCalledTimes(1);

    // The position by the time the coalesced frame actually runs — proves the update reflects
    // the latest scroll position at that point, not whatever was current at the first event.
    simulateScrollPosition(container, 2);
    await waitFor(() => expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument());

    // Once that frame has run (clearing rafId back to null), a later scroll event schedules a
    // new one — the throttle resets every frame rather than firing only ever once.
    fireEvent(container, new Event('scroll'));
    expect(rafSpy).toHaveBeenCalledTimes(2);

    rafSpy.mockRestore();
  });
});

