280	/**
281	 * Fix 1 (Scorer round 1, SFCC-236 Step 4 rework): the 19 tests above all render through the
282	 * `vi.mock('@chakra-ui/react', ...)` at the top of this file, which replaces useMultiStyleConfig
283	 * with a flat `{}` return for every part — none of them ever evaluate the REAL recipe object.
284	 * Proved live by the Scorer: deleting the recipe's HOVER_CAPABLE_QUERY media-query gate entirely
285	 * (making the desktop arrows permanently visible regardless of pointer capability) left the
286	 * whole suite green. These tests import the recipe module directly and call its exported
287	 * baseStyle(), bypassing the mock entirely — same technique as
288	 * zimmSizeChip.css.test.ts / zimmTextInput.css.test.ts.
289	 */
290	describe('ZimmProductCardMedia — real recipe assertions (bypasses the useMultiStyleConfig mock)', () => {
291	  /**
292	   * Behavioural fix, confirmed against the Jira AC ("when on desktop and the user hovers, then
293	   * the arrows appear") and live Figma (Carousel is `hidden="true"` on every Default-state
294	   * instance checked, visible only on the matching Hover-state instance, for both PLP and
295	   * Wishlist). This test used to assert `carousel[HOVER_CAPABLE_QUERY].display === 'flex'` —
296	   * i.e. that ANY hover-capable device (not just an actually-hovering one) revealed the arrows
297	   * at THIS recipe's own level. That was the bug: a device-CAPABILITY check standing in for an
298	   * actual-hover check made the arrows permanently visible on desktop. The
299	   * `[HOVER_CAPABLE_QUERY]: { display: 'flex' }` sub-block that produced that value has been
300	   * removed from `carousel` entirely — the real hover/has(:focus-visible) reveal now lives one layer up,
301	   * on `ZimmProductCard`'s own organism recipe (`zimmProductCard.css.ts` docblock point 6),
302	   * scoped to the whole card via `&:hover`/`&:has(:focus-visible)`, which this Media-only recipe has no
303	   * visibility into (there is no composing organism root here to hover). See that file's own
304	   * "real recipe assertions" describe block for the reveal-rule regression guard.
305	   */
306	  test('carousel (arrows) has no reveal of its own at this recipe level — stays clipped unconditionally, even inside HOVER_CAPABLE_QUERY; indicatorWrapper is unaffected by the fix', () => {
307	    const style = ZimmProductCardMediaRecipe.baseStyle();
308	
309	    // Touch / non-hover-capable pointers (outside the media query): indicator visible, arrows
310	    // clipped. Fix J (SFCC-236): `carousel`'s own unconditional hidden state was `display: 'none'`
311	    // — converted to `clipPath: 'inset(50%)'` (see zimmProductCard.css.ts docblock point 6's own
312	    // Fix J note) so the arrows stay in the DOM/tab order/accessibility tree even while clipped.
313	    // `display` is no longer set by this part at all — the organism's own `&:hover`/
314	    // `&:has(:focus-visible)` reveal rules assert `display: 'flex'` explicitly instead (needed for
315	    // this part's own `justifyContent`/`alignItems`, which this recipe alone can no longer supply
316	    // unconditionally without also making the arrows a flex row while still hidden/clipped).
317	    expect(style.indicatorWrapper.display).toBe('block');
318	    expect((style.carousel as Record<string, unknown>).display).toBeUndefined();
319	    expect(style.carousel.clipPath).toBe('inset(50%)');
320	
321	    // Hover-capable pointers: indicatorWrapper still hides itself via its own
322	    // `[HOVER_CAPABLE_QUERY]` key (unchanged by this fix) — but `carousel` no longer has a
323	    // `[HOVER_CAPABLE_QUERY]` key AT ALL. Regression guard: if that key ever reappears here with
324	    // an unconditional `display: 'flex'`, the permanent-visibility bug is back.
325	    const carousel = style.carousel as Record<string, unknown>;
326	    const indicatorWrapper = style.indicatorWrapper as Record<string, unknown>;
327	    expect(carousel[HOVER_CAPABLE_QUERY]).toBeUndefined();
328	    const indicatorHoverBlock = indicatorWrapper[HOVER_CAPABLE_QUERY] as Record<string, unknown>;
329	    expect(indicatorHoverBlock.display).toBe('none');
330	  });
