396	
397	    // jsdom performs no real layout, so clientWidth/scrollWidth/scrollLeft all default to 0 —
398	    // but they ARE plain definable properties, so a real geometry can be simulated directly.
399	    // Slide width 300 x 3 slides, scrolled to slide index 1 (the 2nd of 3) => scrollLeft 300.
400	    const SIMULATED_SLIDE_WIDTH = 300;
401	    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
