419	/**
420	 * The `scrollend`-only tracking above lags for the whole duration of an active drag (it only
421	 * fires once the gesture settles) — confirmed live once a related fix made the swipe gesture
422	 * itself reachable for the first time. These tests cover the `scroll`-driven live-tracking path
423	 * added alongside it: see index.tsx's own updated comment above the effect for the full
424	 * reasoning. jsdom (this suite's Vitest environment) implements a real, timer-backed
425	 * `requestAnimationFrame`, so the throttled update is genuinely asynchronous here, not merely
426	 * simulated — the same real-rAF-plus-`waitFor` precedent already used by
427	 * list-menu-popover.test.tsx's own double-rAF-deferred assertions.
428	 */
429	describe('ZimmProductCardMedia — scroll listener drives the touch indicator live during an active drag', () => {
430	  const SIMULATED_SLIDE_WIDTH = 300;
431	
432	  /** Same "jsdom performs no real layout, but these are plain definable properties" approach as
433	   *  the `scrollend` test above — sets a plausible clientWidth/scrollWidth/scrollLeft for a
434	   *  given slide index directly. */
435	  const simulateScrollPosition = (container: HTMLElement, slideIndex: number) => {
436	    Object.defineProperty(container, 'clientWidth', { value: SIMULATED_SLIDE_WIDTH, configurable: true });
437	    Object.defineProperty(container, 'scrollWidth', {
438	      value: SIMULATED_SLIDE_WIDTH * GALLERY.length,
439	      configurable: true,
440	    });
441	    Object.defineProperty(container, 'scrollLeft', { value: SIMULATED_SLIDE_WIDTH * slideIndex, configurable: true });
442	  };
443	
444	  test('a real scroll event with a simulated scroll position updates the indicator once the throttled animation frame runs', async () => {
445	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
446	    const container = screen.getByTestId('card-media-scroll');
447	    simulateScrollPosition(container, 1); // 2nd of 3 slides
448	
449	    // fireEvent (not a raw dispatchEvent) routes through RTL's act()-wrapping config, same
450	    // reasoning as the scrollend test above — necessary here too even though the resulting
451	    // setCurrentIndex call is additionally deferred behind a real requestAnimationFrame.
452	    fireEvent(container, new Event('scroll'));
453	
454	    // Unlike the scrollend path, this update is intentionally NOT synchronous — it is coalesced
455	    // behind a real requestAnimationFrame callback, so the assertion has to wait it out rather
456	    // than read the DOM immediately.
457	    await waitFor(() => expect(screen.getByRole('group', { name: 'Image 2 of 3' })).toBeInTheDocument());
458	  });
459	
460	  test('several scroll events fired before the pending animation frame runs are coalesced into a single requestAnimationFrame call, not one per event', async () => {
461	    // spyOn (no mockImplementation) still calls through to jsdom's real rAF — this only adds a
462	    // call-count tripwire on top of the real, unthrottled behavior it would otherwise have.
463	    const rafSpy = vi.spyOn(window, 'requestAnimationFrame');
464	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls />);
465	    const container = screen.getByTestId('card-media-scroll');
466	    simulateScrollPosition(container, 1);
467	
468	    // Simulates the many `scroll` events a real touch-driven drag fires per second, all
469	    // dispatched before the browser has had any chance to run the first queued animation frame.
470	    fireEvent(container, new Event('scroll'));
471	    fireEvent(container, new Event('scroll'));
472	    fireEvent(container, new Event('scroll'));
473	
474	    // The `rafId !== null` guard means only the FIRST of the three calls above actually schedules
475	    // a frame — this is the throttling behavior itself, not merely "it eventually updates".
476	    expect(rafSpy).toHaveBeenCalledTimes(1);
477	
478	    // The position by the time the coalesced frame actually runs — proves the update reflects
479	    // the latest scroll position at that point, not whatever was current at the first event.
480	    simulateScrollPosition(container, 2);
481	    await waitFor(() => expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument());
482	
483	    // Once that frame has run (clearing rafId back to null), a later scroll event schedules a
484	    // new one — the throttle resets every frame rather than firing only ever once.
485	    fireEvent(container, new Event('scroll'));
486	    expect(rafSpy).toHaveBeenCalledTimes(2);
487	
488	    rafSpy.mockRestore();
489	  });
490	});
491	
492	describe('ZimmProductCardMedia — scroll container is keyboard-operable regardless of pointer capability (Fix 5)', () => {
493	  test('ArrowRight/ArrowLeft on the scroll container wrap at both ends, the same as the visible arrows, even with showControls false', () => {
494	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} images={GALLERY} swapOnHover={false} showControls={false} />);
495	    const container = screen.getByTestId('card-media-scroll');
496	
497	    expect(container).toHaveAttribute('tabindex', '0');
498	
499	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // 0 -> 1
500	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // 1 -> 2 (last)
501	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
502	
503	    fireEvent.keyDown(container, { key: 'ArrowRight' }); // wraps 2 -> 0
504	    expect(screen.getByRole('group', { name: 'Image 1 of 3' })).toBeInTheDocument();
505	
506	    fireEvent.keyDown(container, { key: 'ArrowLeft' }); // wraps 0 -> 2 (last)
507	    expect(screen.getByRole('group', { name: 'Image 3 of 3' })).toBeInTheDocument();
508	  });
509	
510	  test('the scroll container is not keyboard-focusable when there is only one image', () => {
511	    wrap(<ZimmProductCardMedia primaryImage={PRIMARY} swapOnHover={false} showControls={false} />);
512	    const container = screen.getByTestId('card-media-scroll');
513	    expect(container).not.toHaveAttribute('tabindex');
514	  });
515	});
