import React, { useEffect, useRef, useState } from 'react';
import { chakra, useMultiStyleConfig } from '@chakra-ui/react';
import { defineMessages, useIntl } from 'react-intl';
import { ZimmSlideIndicator } from '../zimmSlideIndicator';
import { ChevronLeftIcon, ChevronRightIcon, CloseIcon } from '../../../icons';
import { CARD_SLOT } from '../../zimmProductCardShared';

/**
 * Selector contract for a later step (the ZimmProductCard organism, SFCC-236 Step 6): stable
 * `data-card-slot` values on this component's own DOM so that organism's own recipe can target
 * these descendants for hover-reveal styling without reaching into implementation details.
 * Do not rename these values without updating that recipe too:
 *   - "media"     — the outermost element (this component's root)
 *   - "badge"     — the merchandiser badge label, top-left of the image (present only when a
 *                   non-empty `badge` is supplied)
 *   - "close"     — the remove-CTA button (present only when `onRemove` + a usable label exist)
 *   - "carousel"  — the prev/next arrows wrapper (present only when paging is enabled)
 *   - "indicator" — the touch slide-indicator wrapper (present only when there is >1 image)
 */

const messages = defineMessages({
  previousImage: { id: 'product_card_media.pagination.previous', defaultMessage: 'Previous image' },
  nextImage: { id: 'product_card_media.pagination.next', defaultMessage: 'Next image' },
  /**
   * Accessible name for the always-available keyboard-operable scroll container (WCAG 2.1.1) —
   * distinct from the hover-capable-only `carousel` arrows and the touch-only
   * `indicatorWrapper`, this is the underlying paging affordance that exists regardless of
   * pointer capability. See `canNavigateByKeyboard` below.
   */
  galleryLabel: { id: 'product_card_media.gallery.label', defaultMessage: 'Product images' },
});

const ZIMM_PRODUCT_CARD_MEDIA_RECIPE = 'ZimmProductCardMedia';

/** One image the card can show — always a real, non-empty product-photo description. */
export type ZimmProductCardMediaImage = {
  src: string;
  alt: string;
};

export type ZimmProductCardMediaProps = {
  /** The image shown when nothing else applies — always required, even when `images` is supplied. */
  primaryImage: ZimmProductCardMediaImage;
  /**
   * The second image revealed on hover (desktop/hover-capable pointers only), crossfading with
   * `primaryImage`. Ignored while a multi-image `images` gallery is active (>1 entries) — the
   * arrows/indicator paging affordances already give a shopper a way to browse every image, so
   * a hover-swap of just the first two would be a second, inconsistent way to see the same
   * content. Has no effect unless `swapOnHover` is also true.
   */
